/* ARN Inventory • Revisi 1007.2
   Full local-first PWA. Supabase is used when supabase-config.js contains a URL + publishable key.
   No generated artwork is used. All logos are supplied assets.
*/
const APP_KEY='arn_inventory_local_v1001';
const MASTER_KEY='arn_inventory_master_v1001';
const DB0={parts:[],categories:[],tx:[],accounts:[],session:null,meta:{}};
let DB=structuredClone(DB0), MASTER=null, page='Stok', drawerOpen=false, authMode='login';
let stockFilter={category:'Semua',status:'Semua'}, summaryRange='all', summaryStart='', summaryEnd='', supa=null, syncState='Lokal';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const norm=s=>String(s??'').toLowerCase().trim().replace(/\s+/g,' ');
const upper=s=>String(s??'').trim().toUpperCase();
const uid=()=>crypto.randomUUID();
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const localTime=()=>{const d=new Date();return `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`};
const fmtDate=d=>{if(!d)return '-';return new Date(`${d}T00:00:00`).toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'})};
const nowISO=()=>new Date().toISOString();
function save(){DB.meta.lastSaved=Date.now();localStorage.setItem(APP_KEY,JSON.stringify(DB))}
function load(){try{const x=JSON.parse(localStorage.getItem(APP_KEY)||'null');if(x)DB={...DB0,...x}}catch{};for(const k of ['parts','categories','tx','accounts'])if(!Array.isArray(DB[k]))DB[k]=[];if(!DB.meta)DB.meta={}}
function acct(){return DB.accounts.find(a=>a.id===DB.session?.accountId)||null}
function myParts(){return DB.parts.filter(p=>p.accountId===DB.session?.accountId&&p.is_active!==false)}
function myCats(){return DB.categories.filter(c=>c.accountId===DB.session?.accountId&&c.is_active!==false)}
function allMyCats(){return DB.categories.filter(c=>c.accountId===DB.session?.accountId)}
function txFor(id){return DB.tx.filter(t=>t.accountId===DB.session?.accountId&&t.partId===id)}
function stock(p){return txFor(p.id).reduce((n,t)=>n+(t.type==='in'?Number(t.qty):-Number(t.qty)),0)}
function txOrderKey(t){return `${t.date||''} ${t.time||'00:00'} ${t.createdAt||''} ${t.id||''}`}
function stockAfterTransaction(t){let n=0;const rows=txFor(t.partId).slice().sort((a,b)=>txOrderKey(a).localeCompare(txOrderKey(b)));for(const r of rows){n+=r.type==='in'?Number(r.qty):-Number(r.qty);if(r.id===t.id)return n}return stock({id:t.partId})}
function status(q){return q>5?'Normal':q>0?'Menipis':'Kosong'}
function statusClass(s){return s==='Normal'?'ok':s==='Menipis'?'warn':'zero'}
function counts(){const ps=myParts(),qs=ps.map(stock);return{types:ps.length,total:qs.reduce((a,b)=>a+b,0),low:qs.filter(q=>q>0&&q<=5).length,empty:qs.filter(q=>q===0).length}}
function compat(p){if(Array.isArray(p))return p.filter(Boolean).map(String);if(!p)return[];return String(p).split(/\n|•|;/).map(x=>x.trim()).filter(Boolean)}
function searchable(p){
 const related=[];
 const code=norm(p.code||p.name);
 for(const b of MASTER?.battery||[])if(norm(b.code)===code||norm(b.name)===code)related.push(...compat(b.compatibility));
 for(const g of MASTER?.lcd||[])if(norm(g.group)===code||norm(g.name)===code||norm(g.code||'')===code)related.push(...(g.models||[]));
 for(const g of MASTER?.temperedGlass||[])if(norm(g.group)===code||norm(g.name)===code||norm(g.code||'')===code)related.push(...(g.models||g.raw||[]));
 return norm([p.name,p.code,p.category,...compat(p.compatibility),...related].join(' | '))
}
function searchParts(q){const n=norm(q);if(!n)return myParts();const aliases=[n,n.replace(/^tg\s+/,'').replace(/^lcd\s+/,'').replace(/^bat(?:erai)?\s+/,'')].filter(Boolean);const terms=[...new Set(aliases.flatMap(x=>x.split(/\s+/).filter(Boolean)))];return myParts().filter(p=>{const hay=searchable(p);return aliases.some(term=>hay.includes(term))||terms.every(term=>hay.includes(term))})}
function searchAllParts(q){const n=norm(q);const arr=DB.parts.filter(p=>p.accountId===DB.session?.accountId);if(!n)return arr;const aliases=[n,n.replace(/^tg\s+/,'').replace(/^lcd\s+/,'').replace(/^bat(?:erai)?\s+/,'')].filter(Boolean);const terms=[...new Set(aliases.flatMap(x=>x.split(/\s+/).filter(Boolean)))];return arr.filter(p=>{const hay=searchable(p);return aliases.some(term=>hay.includes(term))||terms.every(term=>hay.includes(term))})}

function ensureCat(name,master=false){const n=String(name||'').trim();if(!n)return null;let c=DB.categories.find(x=>x.accountId===DB.session.accountId&&norm(x.name)===norm(n));if(c){if(c.is_active===false)c.is_active=true;return c}c={id:uid(),accountId:DB.session.accountId,name:n,is_active:true,master,createdAt:nowISO()};DB.categories.push(c);return c}
function masterKey(p){return p.masterKey||''}
function parseTGCompatibility(raw=''){
 const out=[],seen=new Set();
 const brands=['Vivo','OPPO','realme','Samsung','Infinix','TECNO','itel','Redmi/POCO','Xiaomi / Redmi','Xiaomi','POCO','iQOO','Redmi','Honor','Huawei','OnePlus','Nokia','Motorola','Oppo','Camon','realme/Narzo'];
 const meta=/^(brand|tipe tg|notch|punch hole|tompel|halaman|acuan stok|semua tipe|semua|tipe)$/i;
 const badWords=/\b(semua tipe|masuk kelompok|tipe tg|notch|punch hole|tompel|waterdrop|halaman|acuan stok)\b/i;
 let activeBrand='';
 const add=(part)=>{
  part=part.replace(/^\d+\.\s*/,'').replace(/\s+/g,' ').trim();
  if(!part||part.length<2||meta.test(part)||badWords.test(part)||/[±]/.test(part)||/\d[.,]\d+\s*["”]/.test(part)||/^[-–—\d\s.]+$/.test(part))return;
  // Strip source-table annotations while preserving actual model names.
  part=part.replace(/\s*[·•]\s*±?[\d.,]+\s*["”]?/g,' ').replace(/\s*[—–-]\s*±?[\d.,]+\s*["”]?/g,' ').trim();
  part=part.replace(/^\(?\s*(NOTCH|PUNCH HOLE|TOMPEL|WATERDROP)\s*\)?/i,'').trim();
  if(!part||meta.test(part)||badWords.test(part)||/[±]/.test(part)||part.length<2)return;
  const n=norm(part);if(!seen.has(n)){seen.add(n);out.push(part)}
 };
 for(let line of String(raw).split(/\n+/).map(x=>x.replace(/\s+/g,' ').trim()).filter(Boolean)){
  line=line.replace(/^\d+\.\s*/,'').trim();
  if(!line||/halaman\s+\d+/i.test(line)||/acuan stok/i.test(line)||/^brand\b/i.test(line)||/^semua tipe yang masuk kelompok/i.test(line))continue;
  // Remove layout-only labels that can be glued to a model row by PDF extraction.
  line=line.replace(/\b(NOTCH|PUNCH HOLE|TOMPEL)\b.*$/i,'').trim();
  if(!line)continue;
  const brandHit=brands.find(b=>new RegExp('^'+b.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?:\\s+|$)','i').test(line));
  if(brandHit){
   const rest=line.slice(brandHit.length).trim();
   if(!rest){activeBrand=brandHit;continue}
   activeBrand=brandHit;
   line=rest;
  }
  if(meta.test(line)||badWords.test(line))continue;
  // Rows with commas are the reliable model lists in the supplied PDF.
  if(line.includes(',')){
   for(const part of line.split(/[,;]+/))add(part);
  }else if(activeBrand && !/[\/]/.test(line) && !/\b(family|±|inch|inci)\b/i.test(line)){
   add(line);
  }
 }
 return out;
}
function seedAccount(){
 if(!MASTER||!DB.session)return;const aid=DB.session.accountId;
 ['Tempered Glass','LCD','Baterai','Tombol Power/Volume','Speaker','Konektor Charger'].forEach(x=>ensureCat(x,true));
 const add=(obj)=>{let existing=DB.parts.find(p=>p.accountId===aid&&masterKey(p)===obj.masterKey);if(!existing&&obj.code)existing=DB.parts.find(p=>p.accountId===aid&&norm(p.code)===norm(obj.code));if(existing){const merged=[...compat(existing.compatibility)];for(const x of compat(obj.compatibility))if(!merged.some(y=>norm(y)===norm(x)))merged.push(x);const patch={master:true,masterSource:existing.masterSource||obj.masterSource,masterKey:existing.masterKey||obj.masterKey,compatibility:merged};if(!existing.name)patch.name=obj.name;if(!existing.code)patch.code=obj.code;if(!existing.categoryId)patch.categoryId=obj.categoryId;if(!existing.category)patch.category=obj.category;if(!existing.unit)patch.unit=obj.unit;Object.assign(existing,patch);return existing}DB.parts.push(obj);return obj};
 for(const g of MASTER.lcd||[]){const c=ensureCat('LCD',true),key=`lcd|${g.source||''}|${g.group||''}|${g.name||''}`;add({id:uid(),accountId:aid,name:`LCD ${g.brand||''} ${g.name||''}`.trim(),code:`LCD-${upper(g.brand||'').replace(/[^A-Z]/g,'').slice(0,6)}-${g.group||''}`,categoryId:c.id,category:c.name,unit:'pcs',purchasePrice:null,salePrice:null,is_active:true,master:true,masterKey:key,masterSource:g.source,compatibility:compat(g.models)})}
 for(const b of MASTER.battery||[]){const c=ensureCat('Baterai',true),key=`battery|${b.code}`;add({id:uid(),accountId:aid,name:b.name||b.code,code:b.code||'',categoryId:c.id,category:c.name,unit:'pcs',purchasePrice:null,salePrice:null,is_active:true,master:true,masterKey:key,masterSource:b.source,compatibility:compat(b.compatibility)})}
 for(const g of MASTER.temperedGlass||[]){const c=ensureCat('Tempered Glass',true),key=`tg|${g.group||''}`;add({id:uid(),accountId:aid,name:String(g.name||'').replace(/^\d+\.\s*/,''),code:g.group||'',categoryId:c.id,category:c.name,unit:'pcs',purchasePrice:null,salePrice:null,is_active:true,master:true,masterKey:key,masterSource:g.source,compatibility:compat(g.models?.length?g.models:parseTGCompatibility(g.raw))})}
 for(const it of MASTER.inventoryItems||[]){const c=ensureCat(it.category==='KONEKTOR'?'Konektor Charger':it.category==='TOMBOL'?'Tombol Power/Volume':it.category==='LCD'?'LCD':it.category==='TG'?'Tempered Glass':it.category||'Lainnya',true);const key=`inventory|${it.code}`;const p=add({id:uid(),accountId:aid,name:it.item_name||it.code,code:it.code,categoryId:c.id,category:c.name,unit:it.unit||'pcs',purchasePrice:null,salePrice:null,is_active:true,master:true,masterKey:key,masterSource:'ARN_STORE_Inventory_Items_REVISI_34_ITEM.csv',compatibility:[]});if(it.item_name&&!compat(p.compatibility).length&&it.category==='TG')p.compatibility=[it.item_name]}
 const openingAliases={'TG-G01':'TG-01','TG-G16':'TG-16','TG-G18':'TG-18'};
 for(const o of MASTER.openingStock||[]){let p=DB.parts.find(x=>x.accountId===aid&&(norm(x.code)===norm(o.code)||norm(x.code)===norm(openingAliases[o.code]||'')));if(!p){const catName=o.code?.startsWith('CON-')?'Konektor Charger':o.code?.startsWith('BTN-')?'Tombol Power/Volume':o.code?.startsWith('LCD-')?'LCD':o.code?.startsWith('TG-')?'Tempered Glass':'Lainnya';const c=ensureCat(catName,true);p=add({id:uid(),accountId:aid,name:o.name||o.code,code:o.code,categoryId:c.id,category:c.name,unit:o.unit||'pcs',purchasePrice:null,salePrice:null,is_active:true,master:true,masterKey:`opening|${o.code}`,masterSource:'ARN_STORE_Stock_Movements_REVISI_34_ITEM.csv',compatibility:compat(o.compatibility)})}const qty=Number(o.qty)||0;if(qty>0&&!DB.tx.some(t=>t.accountId===aid&&t.partId===p.id&&(t.source==='opening'||t.reason==='Stok Awal'))){const sourceDate=/^\d{4}-\d{2}-\d{2}$/.test(o.date||'')?o.date:today();DB.tx.push({id:uid(),accountId:aid,partId:p.id,type:'in',qty,date:sourceDate,time:o.time||'00:00',reason:'Stok Awal',supplier:'',customer:'',phoneModel:'',description:'',jobReference:'',purchasePrice:null,salePrice:null,source:'opening',syncPending:true,createdAt:nowISO(),updatedAt:nowISO()})}}
 DB.meta.seededFor=aid;DB.meta.masterVersion='1007.2';save();
}
async function loadMaster(){try{const r=await fetch('./master-data.json',{cache:'no-store'});MASTER=await r.json();return true}catch(e){console.error(e);return false}}
async function supaClient(){if(supa)return supa;if(!window.ARN_SUPABASE?.url||!window.ARN_SUPABASE?.publishableKey)return null;const mod=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');supa=mod.createClient(window.ARN_SUPABASE.url,window.ARN_SUPABASE.publishableKey);return supa}
function remoteEnabled(){return !!(window.ARN_SUPABASE?.url&&window.ARN_SUPABASE?.publishableKey&&window.ARN_SUPABASE.publishableKey!=='PASTE_YOUR_SUPABASE_PUBLISHABLE_KEY_HERE')}
function backendMisconfigured(){return !!window.ARN_SUPABASE?.url&&!remoteEnabled()}
// Always return the PWA URL, not the Supabase project URL, after email confirmation/OAuth/recovery.
function appRedirectUrl(){
 const u=new URL(window.location.href);
 u.hash=''; u.search='';
 return u.toString();
}

function splash(done){const s=document.createElement('div');s.className='splash';s.innerHTML='<div class="splash-inner"><img class="loading-logo" src="./arn-loading-logo.png" alt="ARN Inventory"><div class="loadbar"><div class="fill"></div><div class="rollbox"></div></div><div class="by">By</div><img class="dev" src="./arn-solutions.png" alt="ARN Solutions"></div>';document.body.appendChild(s);requestAnimationFrame(()=>{s.querySelector('.rollbox').classList.add('go');s.querySelector('.fill').animate([{width:'0%'},{width:'100%'}],{duration:7000,easing:'linear',fill:'forwards'})});let finished=false;const init=Promise.resolve().then(done).finally(()=>{finished=true});setTimeout(()=>{if(!finished&&!document.querySelector('.shell')&&!document.querySelector('.auth')){try{authScreen();}catch(e){console.error('Splash timeout',e)}}},45000);Promise.allSettled([init,new Promise(r=>setTimeout(r,7000))]).then(()=>s.remove())}
function authScreen(){document.body.innerHTML=`<div class="auth"><div class="auth-card"><img class="auth-logo" src="./arn-inventory-header.png" alt="ARN Inventory"><div class="auth-kicker">ARN Inventory <span>•</span> Stok & Part</div><h1>${authMode==='login'?'Masuk':'Daftar'}</h1><p>${authMode==='login'?'Kelola stok dan part dalam satu tempat.':'Buat akun ARN Inventory baru.'}</p>${authMode==='register'?'<div class="field"><label>Nama</label><input id="aname" autocomplete="name" placeholder="Nama"></div>':''}<div class="field"><label>Email</label><input id="aemail" type="email" autocomplete="email" placeholder="nama@email.com"></div><div class="field"><label>Password</label><input id="apass" type="password" autocomplete="current-password" placeholder="Password"></div>${authMode==='register'?'<div class="field"><label>Konfirmasi Password</label><input id="aconf" type="password" autocomplete="new-password" placeholder="Ulangi password"></div>':''}<div id="aerr" class="error"></div><div class="auth-links">${authMode==='login'?'<button class="link" id="forgot">Lupa password</button><button class="link" id="toReg">Daftar</button>':'<span></span><button class="link" id="toLogin">Sudah punya akun?</button>'}</div><button class="primary wide" id="submitAuth">${authMode==='login'?'Masuk':'Daftar'}</button><button class="secondary wide" id="google">${authMode==='login'?'Masuk':'Daftar'} dengan Google</button></div></div>`;
 $('#submitAuth').onclick=doAuth;$('#toReg')?.addEventListener('click',()=>{authMode='register';authScreen()});$('#toLogin')?.addEventListener('click',()=>{authMode='login';authScreen()});$('#forgot')?.addEventListener('click',async()=>{const email=norm($('#aemail').value);if(!remoteEnabled()){$('#aerr').textContent='Masukkan email lalu isi konfigurasi Supabase untuk pemulihan password.';return}if(!email){$('#aerr').textContent='Masukkan email terlebih dahulu.';return}try{const sb=await supaClient();const {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:appRedirectUrl()});if(error)throw error;$('#aerr').textContent='Tautan pemulihan password sudah dikirim ke email tersebut jika akun tersedia.'}catch(e){$('#aerr').textContent=e.message||'Gagal mengirim pemulihan password.'}});$('#google').onclick=async()=>{if(!remoteEnabled()){$('#aerr').textContent='Google tersedia saat provider Google di Supabase dikonfigurasi.';return}try{const sb=await supaClient();const {error}=await sb.auth.signInWithOAuth({provider:'google',options:{redirectTo:appRedirectUrl()}});if(error)throw error}catch(e){$('#aerr').textContent=e.message||'Google login gagal.'}};
}
async function doAuth(){
 const e=norm($('#aemail').value),p=$('#apass').value;
 if(!e||!p){$('#aerr').textContent='Email dan password wajib diisi.';return}
 $('#submitAuth').disabled=true; $('#submitAuth').textContent='Memproses...';
 try{
  if(window.ARN_SUPABASE?.url && !remoteEnabled())throw new Error('Supabase sudah ditentukan, tetapi publishable key belum diisi. Isi key publik ARN Store Part Stock di supabase-config.js.');
  if(remoteEnabled()){
   const sb=await supaClient();
   if(!sb)throw new Error('Koneksi Supabase belum tersedia. Periksa konfigurasi ARN Store Part Stock.');
   if(authMode==='register'){
    const name=$('#aname').value.trim(),conf=$('#aconf').value;
    if(!name){$('#aerr').textContent='Nama wajib diisi.';return}
    if(p!==conf){$('#aerr').textContent='Konfirmasi password tidak sama.';return}
    const {data,error}=await sb.auth.signUp({email:e,password:p,options:{data:{name},emailRedirectTo:appRedirectUrl()}});
    if(error)throw error;
    if(!data.session){
      $('#aerr').textContent='Akun dibuat. Cek email dan tekan Verifikasi Email. Setelah diverifikasi, kamu akan kembali otomatis ke ARN Inventory.';
      return
    }
    await hydrateRemoteAccount(data.user);
   }else{
    const {data,error}=await sb.auth.signInWithPassword({email:e,password:p});if(error)throw error;await hydrateRemoteAccount(data.user);
   }
   save(); await enterAccount();
  }else{
   if(authMode==='register'){
    const name=$('#aname').value.trim(),conf=$('#aconf').value;
    if(!name){$('#aerr').textContent='Nama wajib diisi.';return}
    if(p!==conf){$('#aerr').textContent='Konfirmasi password tidak sama.';return}
    if(DB.accounts.some(a=>a.email===e)){ $('#aerr').textContent='Email sudah terdaftar.';return}
    const a={id:uid(),name,email:e,password:p,role:'user',createdAt:nowISO()};DB.accounts.push(a);DB.session={accountId:a.id};save();await enterAccount();
   }else{
    const a=DB.accounts.find(x=>x.email===e&&x.password===p);if(!a){$('#aerr').textContent='Email atau password salah.';return}
    DB.session={accountId:a.id};save();await enterAccount();
   }
  }
 }catch(err){console.error(err);$('#aerr').textContent=err?.message||'Proses akun gagal. Periksa koneksi dan konfigurasi.'}
 finally{if($('#submitAuth')){$('#submitAuth').disabled=false;$('#submitAuth').textContent=authMode==='login'?'Masuk':'Daftar'}}
}
async function hydrateRemoteAccount(user){
 const sb=await supaClient();
 // Always resolve the profile through the security-definer self-healing RPC first.
 // This prevents a stale local role from hiding Admin Panel after the role is changed in Supabase.
 const repaired=await sb.rpc('arn_ensure_my_account',{p_display_name:user.user_metadata?.name||user.email?.split('@')[0]||'User'});
 let profile=Array.isArray(repaired.data)?repaired.data[0]:repaired.data;
 const currentProfile=await sb.from('arn_profiles').select('account_id,display_name,role').eq('id',user.id).maybeSingle();
 if(currentProfile.error)throw currentProfile.error;
 if(currentProfile.data?.account_id)profile=currentProfile.data;
 if(repaired.error&&!profile?.account_id)throw repaired.error;
 if(!profile?.account_id)throw new Error('Profil ARN Inventory belum memiliki account.');
 const existing=DB.accounts.find(a=>a.remoteUserId===user.id||a.id===profile.account_id);const a=existing||{id:profile.account_id,name:profile.display_name||user.email?.split('@')[0]||'User',email:user.email||'',password:'',role:profile.role||'user',createdAt:nowISO()};a.id=profile.account_id;a.remoteUserId=user.id;a.name=profile.display_name||a.name;a.email=user.email||a.email;a.role=String(profile.role||'user').toLowerCase()==='admin'?'admin':'user';if(!existing)DB.accounts.push(a);DB.session={accountId:a.id,remoteUserId:user.id};
}

async function enterAccount(){if(!DB.session)return;if(!MASTER)await loadMaster();if(remoteEnabled()&&DB.session.remoteUserId)await pullRemoteData();if(MASTER)seedAccount();renderApp();await syncAll()}
function renderApp(){document.body.innerHTML=`<div class="shell"><header class="header"><div class="brand"><img class="header-logo" src="./arn-inventory-header.png" alt="ARN Inventory"></div><div class="header-right"><span class="sync-dot ${syncState==='Tersinkron'?'online':''}" title="${esc(syncState)}"></span><button class="hamb" aria-label="Menu">☰</button></div></header><main class="page" id="page"></main><nav class="bottom">${[['Stok','▣'],['History','◷'],['Ringkasan','▤']].map(([n,i])=>`<button class="nav ${page===n?'active':''}" data-page="${n}"><span>${i}</span><small>${n}</small></button>`).join('')}</nav><div class="overlay"></div><aside class="drawer"><div class="drawerhead"><div><b>Menu</b><small>${esc(acct()?.email||'')}</small></div><button class="iconbtn close">×</button></div>${[['↻','Refresh Data'],['▦','Kelola Kategori'],['▣','Kelola Part'],['⇩','Backup / Ekspor'],['⚙','Pengaturan'],['ⓘ','Tentang Aplikasi']].map(([i,n])=>`<button class="menuitem" data-menu="${n}"><b>${i}</b><span>${n}</span></button>`).join('')}<button class="menuitem logout" id="logout"><b>⇥</b><span>Keluar Akun</span></button></aside></div>`;
 $$('.nav').forEach(b=>b.onclick=()=>{page=b.dataset.page;renderApp()});$('.hamb').onclick=openDrawer;$('.overlay').onclick=closeDrawer;$('.close').onclick=closeDrawer;$('#logout').onclick=async()=>{if(remoteEnabled()&&supa){try{await supa.auth.signOut()}catch{}}DB.session=null;save();authMode='login';authScreen()};$$('[data-menu]').forEach(b=>b.onclick=()=>menuAction(b.dataset.menu));if(page==='Stok')renderStock();if(page==='History')renderHistory();if(page==='Ringkasan')renderSummary()}
function openDrawer(){$('.drawer').classList.add('open');$('.overlay').classList.add('open')}function closeDrawer(){$('.drawer').classList.remove('open');$('.overlay').classList.remove('open')}
function menuAction(x){closeDrawer();if(x==='Refresh Data')refreshData();else if(x==='Kelola Part')partManager();else if(x==='Kelola Kategori')categoryManager();else if(x==='Backup / Ekspor')backupModal();else if(x==='Tentang Aplikasi')aboutModal();else if(x==='Pengaturan')settingsModal();}
function renderStock(){const c=counts();$('#page').innerHTML=`<div class="hero"><div><div class="eyebrow">ARN Inventory <span>•</span> Stok & Part</div><h1>Stok</h1><p>Semua Part, stok, dan kompatibilitas dalam satu tempat.</p></div><button class="filterbtn" id="filter">☷ Filter</button></div><div class="search"><span>⌕</span><input id="q" placeholder="Cari part, kode, model HP, kategori..."></div><div class="stats"><button class="stat" data-stat="all"><small>Total Jenis Part</small><b>${c.types}</b></button><button class="stat" data-stat="total"><small>Total Stok</small><b>${c.total}</b></button><button class="stat" data-stat="low"><small>Menipis</small><b>${c.low}</b></button><button class="stat" data-stat="empty"><small>Kosong</small><b>${c.empty}</b></button></div><div class="actions"><button class="primary" id="in">＋ Stok Masuk</button><button class="secondary" id="out">− Stok Keluar</button></div><section class="section"><div class="sectionhead"><div><h3>Daftar Part</h3><span class="eyebrow">${myParts().length} jenis</span></div></div><div class="card" id="stocklist"></div></section>`;$('#q').oninput=()=>drawStockList($('#q').value);$('#filter').onclick=filterModal;$('#in').onclick=()=>txModal('in');$('#out').onclick=()=>txModal('out');$$('[data-stat]').forEach(b=>b.onclick=()=>statFilter(b.dataset.stat));drawStockList('')}
function statFilter(k){stockFilter=k==='low'?{category:'Semua',status:'Menipis'}:k==='empty'?{category:'Semua',status:'Kosong'}:{category:'Semua',status:'Semua'};renderStock()}
function drawStockList(q=''){const arr=searchParts(q).filter(p=>(stockFilter.category==='Semua'||norm(p.category)===norm(stockFilter.category))&&(stockFilter.status==='Semua'||status(stock(p))===stockFilter.status));$('#stocklist').innerHTML=arr.map(p=>`<button class="listrow partrow" data-id="${p.id}"><span class="iconbox">${iconFor(p.category)}</span><span class="grow"><b>${esc(p.name)}</b><small>${esc(p.code||'Tanpa kode')} <i>·</i> ${esc(p.category)}</small></span><span class="stocknum"><b>${stock(p)}</b><small>${esc(p.unit)}</small><em class="${statusClass(status(stock(p)))}">${status(stock(p))}</em></span></button>`).join('')||'<div class="empty">Tidak ada Part yang sesuai.</div>';$$('.partrow').forEach(b=>b.onclick=()=>partDetail(b.dataset.id))}
function iconFor(c){const n=norm(c);return n.includes('lcd')?'▱':n.includes('bater')?'▣':n.includes('tempered')?'◇':n.includes('konektor')?'⌁':n.includes('speaker')?'◉':'•'}
function renderHistory(){const rows=DB.tx.filter(t=>t.accountId===DB.session?.accountId).sort((a,b)=>String(b.date).localeCompare(String(a.date))||String(b.createdAt||'').localeCompare(String(a.createdAt||'')));$('#page').innerHTML=`<div class="hero"><div><div class="eyebrow">Semua perubahan stok</div><h1>History</h1><p>Setiap Stock In dan Stock Out tercatat sebagai sumber perubahan stok.</p></div></div><div class="actions"><button class="primary" id="hin">＋ Stok Masuk</button><button class="secondary" id="hout">− Stok Keluar</button></div><div class="card">${rows.map(t=>{const p=DB.parts.find(x=>x.id===t.partId);return `<button class="listrow historyrow" data-id="${t.id}"><span class="flow ${t.type}">${t.type==='in'?'↑':'↓'}</span><span class="grow"><b>${esc(p?.name||'Part tidak ditemukan')}</b><small>${esc(t.reason||'')} · ${fmtDate(t.date)} · ${t.type==='in'?'+':'−'}${t.qty}</small></span><span class="pill">${esc(p?.category||'-')}</span></button>`}).join('')||'<div class="empty">Belum ada transaksi.</div>'}</div>`;$('#hin').onclick=()=>txModal('in');$('#hout').onclick=()=>txModal('out');$$('.historyrow').forEach(b=>b.onclick=()=>historyDetail(b.dataset.id))}
function rangeCut(){const d=new Date();if(summaryRange==='day')return today();if(summaryRange==='week'){d.setDate(d.getDate()-6);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}if(summaryRange==='month')return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;if(summaryRange==='range')return summaryStart||'0000-00-00';return '0000-00-00'}
function renderSummary(){const c=counts(),cut=rangeCut(),tx=DB.tx.filter(t=>t.accountId===DB.session?.accountId&&String(t.date)>=cut&&(!summaryEnd||summaryRange!=='range'||String(t.date)<=summaryEnd)),outs=tx.filter(t=>t.type==='out'),ins=tx.filter(t=>t.type==='in');const used={},cats={},models={};for(const t of outs){const p=DB.parts.find(x=>x.id===t.partId);if(!p)continue;used[p.id]=(used[p.id]||0)+Number(t.qty);cats[p.category]=(cats[p.category]||0)+Number(t.qty);if(t.reason==='Dipakai Servis'&&t.phoneModel)models[t.phoneModel]=(models[t.phoneModel]||0)+1}const top=Object.entries(used).sort((a,b)=>b[1]-a[1]),modelTop=Object.entries(models).sort((a,b)=>b[1]-a[1]);$('#page').innerHTML=`<div class="hero"><div><div class="eyebrow">Ringkasan dinamis dari History</div><h1>Ringkasan</h1><p>Angka pemakaian dihitung dari transaksi yang tersimpan.</p></div><button class="filterbtn" id="sumFilter">☷ Periode</button></div><div class="stats"><button class="stat" data-summary-stat="all"><small>Total Jenis Part</small><b>${c.types}</b></button><button class="stat" data-summary-stat="total"><small>Total Stok</small><b>${c.total}</b></button><button class="stat" data-summary-stat="low"><small>Menipis</small><b>${c.low}</b></button><button class="stat" data-summary-stat="empty"><small>Kosong</small><b>${c.empty}</b></button></div><section class="section"><div class="sectionhead"><h3>Part Terpakai</h3><span class="eyebrow">${outs.reduce((n,t)=>n+Number(t.qty),0)} pcs keluar</span></div><div class="card">${top.map(([id,n])=>{const p=DB.parts.find(x=>x.id===id);return `<button class="listrow summary-part" data-id="${id}"><span class="grow"><b>${esc(p?.name||'-')}</b><small>${n} ${esc(p?.unit||'pcs')} keluar</small></span><span class="pill">${esc(p?.category||'-')}</span></button>`}).join('')||'<div class="empty">Belum ada Stock Out.</div>'}</div></section><section class="section"><div class="sectionhead"><h3>Pemakaian per Kategori</h3></div><div class="card">${Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([n,q])=>`<div class="listrow"><span class="grow"><b>${esc(n)}</b><small>Jumlah Part keluar</small></span><span class="pill">${q}</span></div>`).join('')||'<div class="empty">Belum ada pemakaian.</div>'}</div></section><section class="section"><div class="sectionhead"><h3>Tipe HP</h3><span class="eyebrow">Model dari transaksi servis</span></div><div class="card">${modelTop.map(([n,q])=>`<div class="listrow"><span class="grow"><b>${esc(n)}</b><small>${q} transaksi servis</small></span><span class="pill">${q}</span></div>`).join('')||'<div class="empty">Belum ada model HP pada transaksi servis.</div>'}</div></section><section class="section"><div class="sectionhead"><h3>Aktivitas</h3></div><div class="card"><div class="listrow"><span class="grow"><b>${ins.length}</b><small>Transaksi Stock In</small></span><span class="pill">Masuk</span></div><div class="listrow"><span class="grow"><b>${outs.length}</b><small>Transaksi Stock Out</small></span><span class="pill">Keluar</span></div></div></section>`;$('#sumFilter').onclick=summaryFilter;$$('[data-summary-stat]').forEach(b=>b.onclick=()=>statFilter(b.dataset.summaryStat));$$('.summary-part').forEach(b=>b.onclick=()=>partDetail(b.dataset.id))}
function summaryFilter(){const d=modal(`<div class="modalhead"><div><div class="eyebrow">Ringkasan</div><h2>Filter Periode</h2></div><button class="iconbtn" id="x">×</button></div><div class="filter-section"><div class="filter-title">Periode</div><div class="chiprow">${[['all','Semua'],['day','Hari ini'],['week','7 hari'],['month','Bulan ini'],['range','Rentang']].map(([v,n])=>`<button class="chip ${summaryRange===v?'active':''}" data-r="${v}">${n}</button>`).join('')}</div></div><div class="range-fields" id="rangeFields" style="display:${summaryRange==='range'?'grid':'none'}"><div class="field"><label>Mulai</label><input id="rangeStart" type="date" value="${esc(summaryStart)}"></div><div class="field"><label>Sampai</label><input id="rangeEnd" type="date" value="${esc(summaryEnd)}"></div></div><button class="primary wide" id="applyRange" style="display:${summaryRange==='range'?'block':'none'}">Terapkan Rentang</button>`);$('#x').onclick=()=>d.remove();const rangeFields=d.querySelector('#rangeFields'),applyRange=d.querySelector('#applyRange');d.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>{summaryRange=b.dataset.r;d.querySelectorAll('[data-r]').forEach(x=>x.classList.toggle('active',x.dataset.r===summaryRange));rangeFields.style.display=summaryRange==='range'?'grid':'none';applyRange.style.display=summaryRange==='range'?'block':'none';if(summaryRange!=='range'){summaryStart='';summaryEnd='';d.remove();renderSummary()}});d.querySelector('#rangeStart').onchange=e=>summaryStart=e.target.value;d.querySelector('#rangeEnd').onchange=e=>summaryEnd=e.target.value;applyRange.onclick=()=>{if(!summaryStart||!summaryEnd||summaryStart>summaryEnd){alert('Rentang tanggal tidak valid.');return}d.remove();renderSummary()}}
function formatRupiahValue(value){const digits=String(value??'').replace(/\D/g,'');return digits?'Rp'+Number(digits).toLocaleString('id-ID'):''}
function parseRupiahValue(value){const digits=String(value??'').replace(/\D/g,'');return digits?Number(digits):null}
function modal(html){const d=document.createElement('div');d.className='modal';d.innerHTML=`<div class="modalbox">${html}</div>`;document.body.appendChild(d);d.querySelectorAll('#buy,#sell').forEach(el=>{el.value=formatRupiahValue(el.value);el.addEventListener('input',()=>{const start=el.selectionStart,old=el.value;el.value=formatRupiahValue(old);try{el.setSelectionRange(el.value.length,el.value.length)}catch(_){}})});return d}
function partPickerHtml(selected='',id='partSel',query=''){const arr=searchParts(query);return `<div class="field"><label>Part *</label><input id="${id}Search" placeholder="Ketik nama part, kode, model HP..." value="${esc(query)}"><div class="suggest" id="${id}Suggest">${arr.slice(0,12).map(p=>`<button type="button" data-pick="${p.id}"><span>${esc(p.name)}</span><small>${esc(p.code||'')} · stok ${stock(p)}</small></button>`).join('')||'<div class="empty">Part tidak ditemukan.</div>'}</div><input type="hidden" id="${id}" value="${esc(selected)}"><div class="notfound" id="partNotFound" style="display:none">Part tidak ditemukan. Periksa nama part atau pilih dari daftar yang tersedia.<div class="notfound-actions"><button class="secondary" id="choosePart" type="button">Pilih Part</button><button class="primary" id="newPartFromTx" type="button">＋ Tambahkan Part</button></div></div></div>`}
function bindPartPicker(root,id='partSel',prefill=''){const search=root.querySelector(`#${id}Search`),hidden=root.querySelector(`#${id}`),suggest=root.querySelector(`#${id}Suggest`),nf=root.querySelector('#partNotFound');function draw(){const q=search.value;const arr=searchParts(q).slice(0,12);suggest.innerHTML=arr.map(p=>`<button type="button" data-pick="${p.id}"><span>${esc(p.name)}</span><small>${esc(p.code||'')} · stok ${stock(p)}</small></button>`).join('')||'<div class="empty">Part tidak ditemukan.</div>';nf.style.display=q&&!arr.length?'block':'none';suggest.style.display=arr.length?'block':'none'}search.addEventListener('input',draw);suggest.addEventListener('click',e=>{const b=e.target.closest('[data-pick]');if(!b)return;const p=DB.parts.find(x=>x.id===b.dataset.pick);hidden.value=p.id;search.value=p.name;search.dataset.selected=p.id;suggest.style.display='none';nf.style.display='none';root.querySelectorAll('.compat-candidates').forEach(x=>x.remove());});root.querySelector('#choosePart')?.addEventListener('click',()=>{suggest.style.display='block';draw()});root.querySelector('#newPartFromTx')?.addEventListener('click',()=>{newPartModal(search.value.trim(),()=>{const p=DB.parts.find(x=>x.accountId===DB.session.accountId&&norm(x.name)===norm(search.value.trim()));if(p){hidden.value=p.id;search.value=p.name;draw()}})});if(prefill)search.value=prefill;draw()}
function txModal(type,editId=null){const old=editId?DB.tx.find(t=>t.id===editId):null;const p0=old?DB.parts.find(p=>p.id===old.partId):null;const d=modal(`<div class="modalhead"><div><div class="eyebrow">${editId?'Edit transaksi':type==='in'?'Stock In':'Stock Out'}</div><h2>${editId?'Edit Transaksi':type==='in'?'Stok Masuk':'Stok Keluar'}</h2></div><button class="iconbtn" id="x">×</button></div>${partPickerHtml(p0?.id||'', 'partSel', p0?.name||'')}<div class="qty"><button id="minus" type="button">−</button><strong id="qty">${old?.qty||1}</strong><button id="plus" type="button">＋</button></div><div class="field"><label>Tanggal *</label><input id="date" type="date" value="${old?.date||today()}"></div>${type==='in'?`<div class="form-grid"><div class="field"><label>Supplier</label><input id="supplier" value="${esc(old?.supplier||'')}" placeholder="Opsional"></div><div class="field"><label>Harga beli</label><input id="buy" type="text" inputmode="numeric" autocomplete="off" value="${old?.purchasePrice??''}" placeholder="Opsional"></div></div>`:`<div class="field"><label>Alasan *</label><select id="reason"><option value="">Pilih alasan</option>${['Dipakai Servis','Terjual','Retur','Rusak','Hilang','Lainnya'].map(x=>`<option ${old?.reason===x?'selected':''}>${x}</option>`).join('')}</select></div><div id="conditional"></div><div class="field"><label>Harga jual</label><input id="sell" type="text" inputmode="numeric" autocomplete="off" value="${old?.salePrice??''}" placeholder="Opsional"></div>`}<div class="field"><label>Referensi Pekerjaan</label><input id="jobReference" value="${esc(old?.jobReference||'')}" placeholder="Opsional"></div><div id="msg" class="error"></div><div class="modalactions"><button class="secondary" id="cancel">Batal</button><button class="primary" id="saveTx">${editId?'Simpan Perubahan':'Simpan'}</button></div>`);d.querySelector('#x').onclick=()=>d.remove();d.querySelector('#cancel').onclick=()=>d.remove();bindPartPicker(d,'partSel',p0?.name||'');let q=Number(old?.qty||1);const qel=d.querySelector('#qty');d.querySelector('#minus').onclick=()=>{q=Math.max(1,q-1);qel.textContent=q};d.querySelector('#plus').onclick=()=>{q+=1;qel.textContent=q};if(type==='out'){d.querySelector('#reason').onchange=()=>conditionalOut(d,d.querySelector('#reason').value,old);if(old)conditionalOut(d,old.reason,old)}d.querySelector('#saveTx').onclick=()=>saveTx(d,type,editId,q)}
function conditionalOut(d,reason,old){const c=d.querySelector('#conditional');if(!c)return;if(!reason){c.innerHTML='';return}const service=reason==='Dipakai Servis';const fresh=!old;const model='<div class="field"><label>Model HP'+(service?' *':' (opsional)')+'</label><input id="phoneModel" name="phoneModel_'+uid()+'" type="text" autocomplete="off" autocapitalize="off" value="'+esc(old?.phoneModel||'')+'" placeholder="Contoh: Vivo V25e"></div>';const customer=service?'<div class="field"><label>Customer</label><input id="customer" name="customer_'+uid()+'" type="text" autocomplete="off" value="'+esc(old?.customer||'')+'" placeholder="Opsional"></div>':'';const desc=reason==='Lainnya'?'<div class="field"><label>Keterangan</label><input id="description" name="description_'+uid()+'" type="text" autocomplete="off" value="'+esc(old?.description||'')+'" placeholder="Keterangan tambahan"></div>':'';c.innerHTML='<div class="form-grid">'+model+customer+'</div>'+desc;if(fresh){const m=c.querySelector('#phoneModel'),cu=c.querySelector('#customer'),de=c.querySelector('#description');if(m)m.value='';if(cu)cu.value='';if(de)de.value=''}}
function modelVariants(value){
 const base=norm(value).replace(/[^a-z0-9+ ]+/g,' ').replace(/\s+/g,' ').trim();
 if(!base)return[];
 const brands=['vivo','oppo','realme','samsung','infinix','tecno','itel','redmi','poco','iqoo','honor','huawei','xiaomi','oneplus','nokia','motorola','camon','narzo'];
 const out=new Set([base]);
 let x=base;
 for(let i=0;i<2;i++){
   const parts=x.split(' ');
   if(parts.length>1&&brands.includes(parts[0])){parts.shift();x=parts.join(' ');out.add(x)}else break;
 }
 return [...out];
}
function modelMatches(query,entry){
 const a=modelVariants(query),b=modelVariants(entry);
 return a.some(x=>b.includes(x));
}
function compatibleCandidates(model){const n=norm(model);if(!n)return[];return myParts().filter(p=>compat(p.compatibility).some(x=>modelMatches(n,x)))}
function saveTx(d,type,editId,q){const partId=d.querySelector('#partSel')?.value,p=DB.parts.find(x=>x.id===partId),msg=d.querySelector('#msg');if(!p){msg.textContent='Pilih Part atau tambahkan Part baru terlebih dahulu.';return}const oldTx=editId?DB.tx.find(x=>x.id===editId):null;if(editId&&!oldTx){msg.textContent='Transaksi yang diedit tidak ditemukan.';return}const date=d.querySelector('#date')?.value||today(),time=oldTx?.time||localTime();if(type==='out'){const reason=d.querySelector('#reason')?.value||'';if(!reason){msg.textContent='Alasan wajib dipilih.';return}const model=d.querySelector('#phoneModel')?.value.trim()||'';if(reason==='Dipakai Servis'&&!model){msg.textContent='Model HP wajib diisi untuk verifikasi kompatibilitas servis.';return}if(model){const cand=compatibleCandidates(model);if(cand.length>1&&!DB.meta.lastCandidateSelection){candidateModal(cand,model,selectedId=>{const h=$('#partSel'),ss=$('#partSelSearch'),cp=DB.parts.find(x=>x.id===selectedId);if(h)h.value=selectedId;if(ss&&cp){ss.value=cp.name;ss.dataset.selected=selectedId}DB.meta.lastCandidateSelection=selectedId;saveTx(d,type,editId,q)});return}if(cand.length>0&&!cand.some(x=>x.id===p.id)){DB.meta.lastCandidateSelection=null;msg.textContent='Part yang dipilih tidak sesuai kandidat kompatibilitas model HP. Pilih Part yang kompatibel.';return}}DB.meta.lastCandidateSelection=null;let available=stock(p);if(oldTx&&oldTx.partId===p.id&&oldTx.type==='out')available+=Number(oldTx.qty);if(q>available){msg.textContent=`Stok tidak cukup. Stok tersedia ${available} ${p.unit}.`;return}}const t=oldTx||{id:uid(),accountId:DB.session.accountId,createdAt:nowISO()};t.partId=p.id;t.type=type;t.qty=q;t.date=date;t.time=time;t.reason=type==='in'?'Stok Masuk':(d.querySelector('#reason')?.value||'');t.supplier=d.querySelector('#supplier')?.value.trim()||'';t.customer=d.querySelector('#customer')?.value.trim()||'';t.phoneModel=d.querySelector('#phoneModel')?.value.trim()||'';t.description=d.querySelector('#description')?.value.trim()||'';t.jobReference=d.querySelector('#jobReference')?.value.trim()||'';t.purchasePrice=parseRupiahValue(d.querySelector('#buy')?.value);t.salePrice=parseRupiahValue(d.querySelector('#sell')?.value);t.updatedAt=nowISO();t.syncPending=true;if(!editId)DB.tx.push(t);save();d.remove();renderApp();syncAll()}
function candidateModal(cands,model,cb){const d=modal(`<div class="modalhead"><div><div class="eyebrow">Verifikasi kompatibilitas</div><h2>Pilih Part untuk ${esc(model)}</h2><p class="sub">Ditemukan beberapa Part yang kompatibel. Pilih Part fisik yang benar.</p></div><button class="iconbtn" id="x">×</button></div><div class="candidate-list">${cands.map(p=>`<button class="candidate" data-id="${p.id}"><span><b>${esc(p.name)}</b><small>${esc(p.code||'')} · stok ${stock(p)} ${esc(p.unit)}</small></span><span>›</span></button>`).join('')}</div>`);$('#x').onclick=()=>{DB.meta.lastCandidateSelection=null;save();d.remove()};d.querySelectorAll('.candidate').forEach(b=>b.onclick=()=>{d.remove();cb(b.dataset.id)})}
function compatibilityEditorHtml(initial=''){
 return `<div class="field"><label>Kompatibilitas (opsional)</label><div class="compat-tabs"><button type="button" class="compat-tab" id="compatMasterTab">Pilih dari Master</button><button type="button" class="compat-tab active" id="compatManualTab">Ketik Manual</button></div><div id="compatMasterPanel" style="display:none"><div class="compat-search"><span>⌕</span><input id="compatMasterSearch" placeholder="Cari model HP di master..." autocomplete="off"></div><div class="compat-list compat-editor-master-list" id="compatMasterList"></div><div class="smallhint" id="compatMasterHint"></div><div class="modalactions"><button type="button" class="primary" id="compatAddMaster">＋ Tambah yang Dipilih</button></div></div><div id="compatManualPanel"><textarea id="compat" placeholder="Satu model per baris">${esc(initial)}</textarea><div class="smallhint">Model baru yang diketik akan menjadi tambahan master setelah Part disimpan.</div></div></div>`;
}
function bindCompatibilityEditor(root){
 const ta=root.querySelector('#compat'),catSel=root.querySelector('#cat'),masterTab=root.querySelector('#compatMasterTab'),manualTab=root.querySelector('#compatManualTab'),masterPanel=root.querySelector('#compatMasterPanel'),manualPanel=root.querySelector('#compatManualPanel'),search=root.querySelector('#compatMasterSearch'),list=root.querySelector('#compatMasterList'),hint=root.querySelector('#compatMasterHint'),addBtn=root.querySelector('#compatAddMaster');
 if(!ta||!masterTab||!manualTab)return;
 const selected=new Set();
 const category=()=>catSel?.selectedOptions?.[0]?.textContent?.trim()||'';
 const current=()=>compat(ta.value);
 const redraw=()=>{
  const pool=masterCompatibilityModels(category()),q=norm(search.value||''),have=new Set(current().map(norm)),arr=q?pool.filter(x=>norm(x.model).includes(q)):pool;
  list.innerHTML=arr.slice(0,150).map(x=>{const k=norm(x.model),checked=selected.has(k)||have.has(k);return `<button type="button" class="compat-master-row ${checked?'selected':''}" data-model="${esc(x.model)}"><span>${checked?'✓':'○'}</span><span class="grow"><b>${esc(x.model)}</b><small>${esc(x.category)}${x.group?` · ${esc(x.group)}`:''}</small></span></button>`}).join('')||'<div class="empty">Tidak ada model master untuk kategori ini.</div>';
  hint.textContent=arr.length>150?`Menampilkan 150 dari ${arr.length} model ${category()||'kompatibilitas'}. Gunakan pencarian untuk model lainnya.`:`${arr.length} model ${category()||'kompatibilitas'} tersedia di master.`;
 };
 const setTab=master=>{masterTab.classList.toggle('active',master);manualTab.classList.toggle('active',!master);masterPanel.style.display=master?'block':'none';manualPanel.style.display=master?'none':'block';if(master)redraw()};
 masterTab.onclick=()=>setTab(true);manualTab.onclick=()=>setTab(false);search.oninput=redraw;if(catSel)catSel.onchange=()=>{selected.clear();redraw()};
 list.onclick=e=>{const b=e.target.closest('[data-model]');if(!b)return;const k=norm(b.dataset.model);if(selected.has(k))selected.delete(k);else selected.add(k);redraw()};
 addBtn.onclick=()=>{const pool=masterCompatibilityModels(category()),have=current(),seen=new Set(have.map(norm));for(const k of selected){const x=pool.find(v=>norm(v.model)===k);if(x&&!seen.has(k)){have.push(x.model);seen.add(k)}}ta.value=have.join('\n');selected.clear();redraw()};
}
