function deleteConfirm(title,target){const d=modal(`<div class="modalhead"><div><div class="eyebrow">Konfirmasi</div><h2>${title}</h2></div></div><p>Data ini akan dihapus dan tidak dapat dipulihkan.</p><div class="modalactions"><button class="secondary" id="cancel">Batal</button><button class="dangerbtn" id="del" disabled>Hapus (7)</button></div>`);let n=7;const b=$('#del');const timer=setInterval(()=>{n--;b.textContent=n>0?`Hapus (${n})`:'Hapus';if(n<=0){clearInterval(timer);b.disabled=false}},1000);$('#cancel').onclick=()=>{clearInterval(timer);d.remove()};b.onclick=async()=>{clearInterval(timer);if(target?.kind==='part'){const p=DB.parts.find(x=>x.id===target.id);if(!p){d.remove();return}DB.parts=DB.parts.filter(x=>x.id!==target.id);DB.meta.deletedParts=[...(DB.meta.deletedParts||[]),target.id]}else{const id=typeof target==='string'?target:target?.id;DB.tx=DB.tx.filter(t=>t.id!==id);DB.meta.deletedTx=[...(DB.meta.deletedTx||[]),id]}save();d.remove();renderApp();await syncAll()}}
