function exportCSV(kind){let rows;if(kind==='history'){rows=[['tanggal','jam','part','kode','kategori','tipe','jumlah','stok_setelah','alasan','supplier','customer','model_hp','referensi_pekerjaan','keterangan','harga_beli','harga_jual']];DB.tx.filter(t=>t.accountId===DB.session.accountId).sort((a,b)=>`${a.date} ${a.time||''}`.localeCompare(`${b.date} ${b.time||''}`)).forEach(t=>{const p=DB.parts.find(x=>x.id===t.partId);rows.push([t.date,t.time||'',p?.name||'',p?.code||'',p?.category||'',t.type,t.qty,stockAfterTransaction(t),t.reason||'',t.supplier||'',t.customer||'',t.phoneModel||'',t.jobReference||'',t.description||'',t.purchasePrice??'',t.salePrice??''])})}else{rows=[['part','kode','kategori','unit','stok','status','kompatibilitas']];myParts().forEach(p=>rows.push([p.name,p.code||'',p.category,p.unit,stock(p),status(stock(p)),compat(p.compatibility).join(' | ')]))}const csv='\ufeff'+rows.map(r=>r.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=kind==='history'?'ARN-Inventory-History.csv':'ARN-Inventory-Stok.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
