function stableCompatId(partId,model){const x=`${partId}|${norm(model)}`;let h1=2166136261,h2=2166136261,h3=2166136261,h4=2166136261;for(let i=0;i<x.length;i++){const c=x.charCodeAt(i);h1=Math.imul(h1^c,16777619);h2=Math.imul(h2^(c+i),16777619);h3=Math.imul(h3^(c*3+i),16777619);h4=Math.imul(h4^(c*7+i),16777619)}const hx=n=>Math.abs(n>>>0).toString(16).padStart(8,'0');const hex=hx(h1)+hx(h2)+hx(h3)+hx(h4);return `${hex.slice(0,8)}-${hex.slice(8,12)}-4${hex.slice(13,16)}-8${hex.slice(17,20)}-${hex.slice(20,32)}`}
function inferMasterKey(x){
 if(x.master_key)return x.master_key;
 if(x.master&&x.code){
   const c=String(x.code);
   if(c.startsWith('LCD-'))return `legacy-lcd|${c}`;
   if(c.startsWith('TG-'))return `legacy-tg|${c}`;
   if(c.startsWith('CON-')||c.startsWith('BTN-')||c==='LCD-001')return `opening|${c}`;
   return `legacy-master|${c}`;
 }
 return '';
}
function partDetail(id){const p=DB.parts.find(x=>x.id===id);if(!p)return;const hasHistory=txFor(id).length>0,inactive=p.is_active===false,canDelete=!p.master&&!hasHistory,actionLabel=inactive?'Aktifkan Part':canDelete?'Hapus Part':'Nonaktifkan Part';const d=modal(`<div class="modalhead"><div><div class="eyebrow">Detail Part</div><h2>${esc(p.name)}</h2></div><button class="iconbtn" id="x">×</button></div><div class="detailgrid"><div><small>Kode</small><b>${esc(p.code||'-')}</b></div><div><small>Kategori</small><b>${esc(p.category)}</b></div><div><small>Unit</small><b>${esc(p.unit)}</b></div><div><small>Stok</small><b>${stock(p)} · ${status(stock(p))}</b></div><div><small>Harga beli</small><b>${p.purchasePrice??'-'}</b></div><div><small>Harga jual</small><b>${p.salePrice??'-'}</b></div></div><button type="button" class="compat compat-open" id="openCompat"><span><b>Lihat Kompatibilitas</b><small>${compat(p.compatibility).length} model terdaftar</small></span><strong>›</strong></button><div class="section"><div class="sectionhead"><h3>History Part</h3></div><div class="card">${txFor(id).sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(t=>`<button class="listrow historyrow" data-id="${t.id}"><span class="flow ${t.type}">${t.type==='in'?'↑':'↓'}</span><span class="grow"><b>${t.type==='in'?'Stock In':'Stock Out'} · ${t.qty}</b><small>${esc(t.reason||'')} · ${fmtDate(t.date)}</small></span></button>`).join('')||'<div class="empty">Belum ada transaksi.</div>'}</div></div><div class="modalactions"><button class="secondary" id="edit">Edit Part</button><button class="dangerbtn" id="removePart">${actionLabel}</button><button class="primary" id="close">Tutup</button></div>`);$('#x').onclick=()=>d.remove();$('#close').onclick=()=>d.remove();$('#openCompat').onclick=()=>compatModal(p);$('#edit').onclick=()=>{d.remove();editPartModal(p.id)};$('#removePart').onclick=()=>{if(inactive||!canDelete){p.is_active=!inactive;p.updatedAt=nowISO();p.syncPending=true;save();d.remove();renderApp();syncAll();return}deleteConfirm('Hapus Part Ini?',{kind:'part',id:p.id});d.remove()};d.querySelectorAll('.historyrow').forEach(b=>b.onclick=()=>{d.remove();historyDetail(b.dataset.id)})}
function masterCompatibilityModels(categoryName=''){
 const out=new Map(),wanted=norm(categoryName);
 const sameCategory=c=>{const n=norm(c||'');return !wanted||n===wanted||(wanted==='battery'&&n==='baterai')||(wanted==='tg'&&n==='tempered glass')};
 const add=(raw,category='Master',group='',source='Master')=>{
  if(raw==null)return;
  const arr=Array.isArray(raw)?raw:[raw];
  for(let value of arr){
   let s=String(value||'').replace(/\s+Cek FPC\/panel.*$/i,'').replace(/\s+\d+\s*$/,'').trim();
   if(!s)continue;
   for(const part of s.split(/\s*\/\s*|\s*;\s*|\s*,\s*|\s*[•]\s*|\n/)){
    const model=part.trim().replace(/^\d+\.\s*/,'').trim();
    if(!model)continue;
    const key=norm(model);
    if(key&&!out.has(key))out.set(key,{model,category,group,source});
   }
  }
 };
 if(!wanted||wanted==='lcd')for(const g of MASTER?.lcd||[])add(g.models,'LCD',g.group,g.source||'Master LCD');
 if(!wanted||wanted==='baterai'||wanted==='battery')for(const b of MASTER?.battery||[])add(b.compatibility,'Baterai',b.code,b.source||'Master Battery');
 if(!wanted||wanted==='tempered glass'||wanted==='tg')for(const g of MASTER?.temperedGlass||[])add(g.models?.length?g.models:g.raw,'Tempered Glass',g.group,g.source||'Master Tempered Glass');
 for(const p of DB.parts.filter(x=>x.master&&sameCategory(x.category)))for(const model of compat(p.compatibility))add(model,p.category||categoryName,p.code||'',p.masterSource||'Master Part');
 for(const p of DB.parts.filter(x=>!x.master&&sameCategory(x.category)))for(const model of compat(p.compatibility))add(model,p.category||categoryName,'Tambahan', 'Tambahan');
 return [...out.values()].sort((a,b)=>a.model.localeCompare(b.model,'id',{numeric:true,sensitivity:'base'}));
}
async function compatModal(p){
 const d=modal(`<div class="modalhead"><div><div class="eyebrow">Kompatibilitas</div><h2>${esc(p.name)}</h2><p class="sub">Pilih model dari master atau ketik model baru. Model baru akan menjadi tambahan master kompatibilitas.</p></div><button class="iconbtn" id="x">×</button></div><div class="compat-tabs"><button type="button" class="compat-tab active" id="masterTab">Pilih dari Master</button><button type="button" class="compat-tab" id="manualTab">Ketik Manual</button></div><div id="masterPanel"><div class="compat-search"><span>⌕</span><input id="mq" placeholder="Cari model HP di master..." autocomplete="off"></div><div class="compat-list compat-modal-list" id="masterList"></div><div class="smallhint" id="masterHint"></div><div class="modalactions"><button class="primary" id="addMaster">＋ Tambah yang Dipilih</button></div></div><div id="manualPanel" style="display:none"><div class="field"><label>Model HP baru</label><input id="newCompat" placeholder="Contoh: Vivo Y15s" autocomplete="off"></div><div class="smallhint">Jika model belum ada di master, model ini akan ditambahkan sebagai kompatibilitas baru dan tersedia pada pilihan master berikutnya.</div><div class="modalactions"><button class="secondary" id="addCompat">＋ Tambah Kompatibilitas</button></div></div><div class="section"><div class="sectionhead"><h3>Kompatibilitas Part</h3><span class="eyebrow" id="compatCount"></span></div><div class="compat-list compat-modal-list" id="clist"></div></div><div class="modalactions"><button class="primary" id="close">Tutup</button></div>`);
 let items=compat(p.compatibility);
 let masterPool=masterCompatibilityModels(p.category);
 const selected=new Set();
 const normSelected=()=>new Set(items.map(x=>norm(x)));
 const loadCombined=async()=>{
  if(!remoteEnabled()||!DB.session?.remoteUserId)return;
  try{
   const sb=await supaClient();
   const {data,error}=await sb.from('arn_part_compatibilities').select('model,source').eq('part_id',p.id);
   if(error)throw error;
   items=(data||[]).map(x=>String(x.model||'').trim()).filter(Boolean).filter((x,i,a)=>a.findIndex(y=>norm(y)===norm(x))===i);
   p.compatibility=items;save();
  }catch(e){console.error('loadCombinedCompat',e)}
 };
 const loadManualPool=async()=>{
  if(!remoteEnabled()||!DB.session?.remoteUserId)return;
  try{
   const sb=await supaClient();
   const {data,error}=await sb.from('arn_part_compatibilities').select('model,source').eq('part_id',p.id);
   if(error)throw error;
   for(const x of data||[])if(x?.model)masterPool.push({model:String(x.model).trim(),category:p.category,source:x.source==='manual'?'Tambahan':'Master'});
   const m=new Map();for(const x of masterPool){const k=norm(x.model);if(k&&!m.has(k))m.set(k,x)}masterPool=[...m.values()].sort((a,b)=>a.model.localeCompare(b.model,'id',{numeric:true,sensitivity:'base'}));
  }catch(e){console.error('loadManualCompatPool',e)}
 };
 const drawCurrent=()=>{
  const q=norm(d.querySelector('#mq')?.value||'');
  const a=q?masterPool.filter(x=>norm(x.model).includes(q)):masterPool;
  const selectedNow=normSelected();
  d.querySelector('#masterList').innerHTML=a.slice(0,150).map(x=>{
   const k=norm(x.model),checked=selected.has(k)||selectedNow.has(k);
   return `<button type="button" class="compat-master-row ${checked?'selected':''}" data-model="${esc(x.model)}"><span>${checked?'✓':'○'}</span><span class="grow"><b>${esc(x.model)}</b><small>${esc(x.category||p.category||'Kompatibilitas')}${x.group?` · ${esc(x.group)}`:''}</small></span></button>`;
  }).join('')||'<div class="empty">Model master tidak ditemukan.</div>';
  d.querySelector('#masterHint').textContent=a.length>150?`Menampilkan 150 dari ${a.length} model. Gunakan pencarian untuk model lainnya.`:`${a.length} model tersedia di master.`;
  d.querySelector('#compatCount').textContent=`${items.length} model`;
  d.querySelector('#clist').innerHTML=items.map(x=>`<div class="compat-item"><span>${esc(x)}</span></div>`).join('')||'<div class="empty">Belum ada model kompatibel.</div>';
 };
 const setTab=(manual)=>{
  d.querySelector('#masterTab').classList.toggle('active',!manual);d.querySelector('#manualTab').classList.toggle('active',manual);
  d.querySelector('#masterPanel').style.display=manual?'none':'block';d.querySelector('#manualPanel').style.display=manual?'block':'none';
 };
 const addModels=async(models)=>{
  const unique=[];const have=normSelected();
  for(const raw of models){const model=String(raw||'').trim();const k=norm(model);if(model&&k&&!have.has(k)){have.add(k);unique.push(model)}}
  if(!unique.length){drawCurrent();return true}
  if(remoteEnabled()&&DB.session?.remoteUserId){
   const sb=await supaClient();
   for(const model of unique){
    const normalized_model=norm(model);
    const {error}=await sb.from('arn_part_compatibilities').upsert({part_id:p.id,model,normalized_model,source:masterPool.some(x=>norm(x.model)===normalized_model)?'master':'manual'},{onConflict:'part_id,normalized_model'});
    if(error){console.error('save compatibility',error);alert('Gagal menyimpan kompatibilitas tipe HP: '+model+'. '+(error.message||''));return false}
   }
  }
  items.push(...unique);p.compatibility=items;p.syncPending=!remoteEnabled();save();drawCurrent();
  if(!remoteEnabled())syncAll();else{syncState='Tersinkron';renderSyncDot()}
 };
 d.querySelector('#x').onclick=()=>d.remove();d.querySelector('#close').onclick=()=>d.remove();
 d.querySelector('#masterTab').onclick=()=>setTab(false);d.querySelector('#manualTab').onclick=()=>setTab(true);
 d.querySelector('#mq').oninput=drawCurrent;
 d.querySelector('#masterList').onclick=e=>{const b=e.target.closest('[data-model]');if(!b)return;const k=norm(b.dataset.model);if(selected.has(k))selected.delete(k);else selected.add(k);drawCurrent()};
 d.querySelector('#addMaster').onclick=async()=>{const models=[...selected].map(k=>masterPool.find(x=>norm(x.model)===k)?.model).filter(Boolean);await addModels(models);selected.clear();drawCurrent()};
 d.querySelector('#addCompat').onclick=async()=>{
  const model=d.querySelector('#newCompat').value.trim();if(!model){alert('Model HP wajib diisi.');return}
  const inMaster=masterPool.find(x=>norm(x.model)===norm(model));
  if(inMaster){const ok=await addModels([inMaster.model]);if(ok!==false){d.querySelector('#newCompat').value='';setTab(false)}return}
  await addModels([model]);
  if(!masterPool.some(x=>norm(x.model)===norm(model))){masterPool.push({model,category:p.category,source:'Tambahan'});masterPool.sort((a,b)=>a.model.localeCompare(b.model,'id',{numeric:true,sensitivity:'base'}))}
  d.querySelector('#newCompat').value='';setTab(false);drawCurrent();
 };
 await loadCombined();await loadManualPool();drawCurrent();
}
function editPartModal(id){const p=DB.parts.find(x=>x.id===id);if(!p)return;const cats=myCats().slice();if(p.categoryId&&!cats.some(c=>c.id===p.categoryId)){const current=DB.categories.find(c=>c.id===p.categoryId);if(current)cats.unshift(current)}const d=modal(`<div class="modalhead"><div><div class="eyebrow">Part</div><h2>Edit Part</h2></div><button class="iconbtn" id="x">×</button></div><div class="field"><label>Nama Part *</label><input id="pn" value="${esc(p.name)}"></div><div class="field"><label>Kode</label><input id="pc" value="${esc(p.code||'')}"></div><div class="field"><label>Kategori *</label><div class="select-add"><select id="cat">${cats.map(c=>`<option value="${c.id}" ${c.id===p.categoryId?'selected':''}>${esc(c.name)}${c.is_active===false?' (Nonaktif)':''}</option>`).join('')}</select><button id="newCat" type="button">＋ Baru</button></div></div><div class="field"><label>Satuan</label><input id="unit" value="${esc(p.unit)}"></div><div class="form-grid"><div class="field"><label>Harga beli</label><input id="buy" type="text" inputmode="numeric" autocomplete="off" value="${p.purchasePrice??''}"></div><div class="field"><label>Harga jual</label><input id="sell" type="text" inputmode="numeric" autocomplete="off" value="${p.salePrice??''}"></div></div>${compatibilityEditorHtml(compat(p.compatibility).join('\n'))}<div id="msg" class="error"></div><div class="modalactions"><button class="secondary" id="cancel">Batal</button><button class="primary" id="save">Simpan</button></div>`);$('#x').onclick=()=>d.remove();$('#cancel').onclick=()=>d.remove();$('#newCat').onclick=()=>inlineCategory(d,()=>refreshPartCategory(d));bindCompatibilityEditor(d);$('#save').onclick=()=>{const n=$('#pn').value.trim(),c=DB.categories.find(x=>x.id===$('#cat').value);if(!n||!c){$('#msg').textContent='Nama dan kategori wajib diisi.';return}p.name=n;p.code=$('#pc').value.trim();p.categoryId=c.id;p.category=c.name;p.unit=$('#unit').value.trim()||'pcs';p.purchasePrice=parseRupiahValue($('#buy').value);p.salePrice=parseRupiahValue($('#sell').value);p.compatibility=$('#compat').value.split(/\n/).map(x=>x.trim()).filter(Boolean);p.updatedAt=nowISO();p.syncPending=true;save();d.remove();renderApp();syncAll()}}
async function pullRemoteData(){if(!remoteEnabled()||!DB.session?.remoteUserId)return;try{const sb=await supaClient(),aid=DB.session.accountId;const [cr,pr,tr]=await Promise.all([sb.from('arn_categories').select('id,account_id,name,is_active,master,created_at,updated_at').eq('account_id',aid),sb.from('arn_parts').select('id,account_id,name,code,category_id,unit,purchase_price,sale_price,is_active,master,master_source,master_key,created_at,updated_at').eq('account_id',aid),sb.from('arn_stock_transactions').select('id,account_id,part_id,transaction_type,quantity,reason,movement_date,movement_time,supplier,customer,phone_model,description,job_reference,purchase_price,sale_price,created_at,updated_at').eq('account_id',aid)]);if(cr.error)throw cr.error;if(pr.error)throw pr.error;if(tr.error)throw tr.error;const remoteCats=cr.data||[],remoteParts=pr.data||[],remoteTx=tr.data||[],rc=new Set(remoteCats.map(x=>x.id)),rp=new Set(remoteParts.map(x=>x.id)),rt=new Set(remoteTx.map(x=>x.id)),deletedParts=new Set(DB.meta.deletedParts||[]);DB.categories=DB.categories.filter(c=>c.accountId!==aid||(c.syncPending||c.dirty)||rc.has(c.id));for(const c of remoteCats){const l=DB.categories.find(x=>x.id===c.id)||DB.categories.find(x=>x.accountId===aid&&norm(x.name)===norm(c.name));const v={id:l?.id||c.id,accountId:aid,name:c.name,is_active:c.is_active,master:!!c.master,syncPending:false,createdAt:c.created_at,updatedAt:c.updated_at};if(l)Object.assign(l,v);else DB.categories.push(v)}const remoteToLocalPart=new Map();DB.parts=DB.parts.filter(p=>p.accountId!==aid||(p.syncPending||p.dirty)||rp.has(p.id));for(const r of remoteParts){if(deletedParts.has(r.id))continue;let l=DB.parts.find(x=>x.id===r.id);const inferred=inferMasterKey(r);if(!l&&inferred)l=DB.parts.find(x=>x.accountId===aid&&x.masterKey===inferred);if(!l&&r.code)l=DB.parts.find(x=>x.accountId===aid&&norm(x.code)===norm(r.code));const key=r.master_key||l?.masterKey||inferred;const cat=DB.categories.find(c=>c.id===r.category_id)||DB.categories.find(c=>c.accountId===aid&&norm(c.name)===norm((remoteCats.find(x=>x.id===r.category_id)||{}).name||''));const v={id:l?.id||r.id,accountId:aid,name:r.name,code:r.code||'',categoryId:cat?.id||null,category:cat?.name||l?.category||'',unit:r.unit||'pcs',purchasePrice:r.purchase_price,salePrice:r.sale_price,is_active:r.is_active,master:!!r.master,masterKey:key,masterSource:r.master_source||null,compatibility:l?.compatibility||[],syncPending:false,createdAt:r.created_at,updatedAt:r.updated_at};if(l)Object.assign(l,v);else DB.parts.push(v);remoteToLocalPart.set(r.id,v.id)}const ids=remoteParts.filter(r=>!deletedParts.has(r.id)).map(x=>x.id);if(ids.length){const {data:compatRows,error}=await sb.from('arn_part_compatibilities').select('part_id,model,source').in('part_id',ids);if(error)throw error;for(const rid of ids){const p=DB.parts.find(x=>x.id===remoteToLocalPart.get(rid)||x.id===rid);if(p&&!p.syncPending&&!p.dirty)p.compatibility=[]}for(const r of compatRows||[]){const p=DB.parts.find(x=>x.id===remoteToLocalPart.get(r.part_id)||x.id===r.part_id);if(p&&!p.syncPending&&!p.dirty)p.compatibility.push(r.model)}}const tomb=new Set(DB.meta.deletedTx||[]);DB.tx=DB.tx.filter(t=>t.accountId!==aid||(t.syncPending||t.dirty)||rt.has(t.id)||tomb.has(t.id));for(const r of remoteTx){if(tomb.has(r.id))continue;const l=DB.tx.find(x=>x.id===r.id);const v={id:l?.id||r.id,accountId:aid,partId:remoteToLocalPart.get(r.part_id)||r.part_id,type:r.transaction_type,qty:Number(r.quantity),reason:r.reason||'',date:r.movement_date,time:r.movement_time||l?.time||'00:00',supplier:r.supplier||'',customer:r.customer||'',phoneModel:r.phone_model||'',description:r.description||'',jobReference:r.job_reference||'',purchasePrice:r.purchase_price,salePrice:r.sale_price,createdAt:r.created_at,updatedAt:r.updated_at,syncPending:false};if(l&&!l.syncPending&&!l.dirty)Object.assign(l,v);else if(!l)DB.tx.push(v)}save()}catch(e){console.error('pullRemoteData',e);syncState='Belum tersinkron';renderSyncDot()}}
async function refreshData(){if(remoteEnabled()&&DB.session?.remoteUserId)await pullRemoteData();await syncAll();renderApp()}
async function syncAll(){if(!navigator.onLine){syncState='Belum tersinkron';renderSyncDot();return}if(!remoteEnabled()||!DB.session?.remoteUserId){syncState='Lokal';renderSyncDot();return}syncState='Menyinkronkan...';renderSyncDot();try{const sb=await supaClient(),aid=DB.session.accountId;for(const id of DB.meta.deletedTx||[]){const {error}=await sb.from('arn_stock_transactions').delete().eq('id',id).eq('account_id',aid);if(error)throw error}for(const id of DB.meta.deletedParts||[]){const {error}=await sb.from('arn_parts').delete().eq('id',id).eq('account_id',aid);if(error)throw error}const cats=allMyCats().map(c=>({id:c.id,account_id:aid,name:c.name,is_active:c.is_active,master:!!c.master,created_at:c.createdAt||nowISO(),updated_at:c.updatedAt||nowISO()}));if(cats.length){const {error}=await sb.from('arn_categories').upsert(cats,{onConflict:'id'});if(error)throw error}const deleted=new Set(DB.meta.deletedParts||[]);const parts=DB.parts.filter(p=>p.accountId===aid&&!deleted.has(p.id)).map(p=>({id:p.id,account_id:aid,name:p.name,code:p.code||null,category_id:p.categoryId||null,unit:p.unit||'pcs',purchase_price:p.purchasePrice,sale_price:p.salePrice,is_active:p.is_active!==false,master:!!p.master,master_source:p.masterSource||null,master_key:p.masterKey||null,created_at:p.createdAt||nowISO(),updated_at:p.updatedAt||nowISO()}));if(parts.length){const {error}=await sb.from('arn_parts').upsert(parts,{onConflict:'id'});if(error)throw error;for(const p of DB.parts.filter(p=>p.accountId===aid&&!deleted.has(p.id))){const {error:delErr}=await sb.from('arn_part_compatibilities').delete().eq('part_id',p.id);if(delErr)throw delErr;const comp=compat(p.compatibility).map(model=>({id:stableCompatId(p.id,model),account_id:aid,part_id:p.id,phone_model:model,source:'manual'}));if(comp.length){const {error}=await sb.from('arn_part_compatibilities').upsert(comp,{onConflict:'id'});if(error)throw error}}}const tx=DB.tx.filter(t=>t.accountId===aid).map(t=>({id:t.id,account_id:aid,part_id:t.partId,transaction_type:t.type,quantity:Number(t.qty),reason:t.reason||null,movement_date:t.date,movement_time:t.time||'00:00',supplier:t.supplier||null,customer:t.customer||null,phone_model:t.phoneModel||null,description:t.description||null,job_reference:t.jobReference||null,purchase_price:t.purchasePrice,sale_price:t.salePrice,created_at:t.createdAt||nowISO(),updated_at:t.updatedAt||nowISO()}));if(tx.length){const {error}=await sb.from('arn_stock_transactions').upsert(tx,{onConflict:'id'});if(error)throw error}DB.meta.deletedTx=[];DB.meta.deletedParts=[];for(const c of allMyCats()){c.syncPending=false;c.dirty=false}for(const p of DB.parts.filter(p=>p.accountId===aid)){p.syncPending=false;p.dirty=false}for(const t of DB.tx.filter(t=>t.accountId===aid)){t.syncPending=false;t.dirty=false}save();syncState='Tersinkron';renderSyncDot()}catch(e){console.error('syncAll',e);syncState='Belum tersinkron';renderSyncDot()}}
function renderSyncDot(){const el=$('.sync-dot');if(el){el.className='sync-dot '+(syncState==='Tersinkron'?'online':'')}}
document.addEventListener('dblclick',e=>{if(!e.target.closest('input,textarea,select'))e.preventDefault()},{passive:false});
window.addEventListener('online',()=>syncAll());window.addEventListener('offline',()=>{syncState='Belum tersinkron';renderSyncDot()});
async function showPasswordRecovery(){const d=modal(`<div class="modalhead"><div><div class="eyebrow">Pemulihan Akun</div><h2>Password Baru</h2><p class="sub">Buat password baru untuk akun ini.</p></div></div><div class="field"><label>Password baru</label><input id="newPass" type="password" autocomplete="new-password"></div><div class="field"><label>Konfirmasi password</label><input id="newPass2" type="password" autocomplete="new-password"></div><div id="recoveryMsg" class="error"></div><div class="modalactions"><button class="primary" id="savePass">Simpan Password</button></div>`);$('#savePass').onclick=async()=>{const a=$('#newPass').value,b=$('#newPass2').value;if(a.length<6){$('#recoveryMsg').textContent='Password minimal 6 karakter.';return}if(a!==b){$('#recoveryMsg').textContent='Konfirmasi password tidak sama.';return}const sb=await supaClient();const {error}=await sb.auth.updateUser({password:a});if(error){$('#recoveryMsg').textContent=error.message||'Gagal mengubah password.';return}d.remove();alert('Password berhasil diperbarui.')}}
async function boot(){load();if(remoteEnabled()){try{const sb=await supaClient();sb.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'&&session)showPasswordRecovery()});const {data}=await sb.auth.getSession();if(data?.session?.user)await hydrateRemoteAccount(data.session.user)}catch(e){console.error(e)}}if(!DB.session){authScreen();return}await enterAccount()}
splash(boot);
